-- ============================================
-- LUMA — Thème 9 : MOYEN 1/3 x4 — Explorer un donjon à plusieurs salles avec choix tactiques
-- ============================================


update scenarios set content = '{"characters": {"gamemaster": "le maître du jeu", "ally": "votre allié"}, "start_node": "n1", "nodes": {"n1": {"speaker": "gamemaster", "text": "Your party enters the first chamber — three doors lie ahead, each marked with different symbols.", "text_fr": "Votre groupe entre dans la première chambre — trois portes se trouvent devant, chacune marquée de symboles différents.", "choices": [{"text": "Take the door marked with a flame symbol.", "text_fr": "Prends la porte marquée d''un symbole de flamme.", "next": "n2"}, {"text": "Take the door marked with a shield symbol.", "text_fr": "Prends la porte marquée d''un symbole de bouclier.", "next": "n2b"}, {"text": "Take the door marked with an eye symbol.", "text_fr": "Prends la porte marquée d''un symbole d''œil.", "next": "n2c"}]}, "n2": {"speaker": "gamemaster", "text": "The flame door leads to a room with fire traps activated by movement.", "text_fr": "La porte flamme mène à une salle avec des pièges de feu activés par le mouvement.", "choices": [{"text": "Move carefully, watching the floor patterns for triggers.", "text_fr": "Avance prudemment, en observant les motifs du sol pour les déclencheurs.", "next": "n3"}]}, "n2b": {"speaker": "gamemaster", "text": "The shield door leads to a room with a sleeping guardian statue.", "text_fr": "La porte bouclier mène à une salle avec une statue gardienne endormie.", "choices": [{"text": "Move quietly, trying not to wake the guardian.", "text_fr": "Avance silencieusement, en essayant de ne pas réveiller le gardien.", "next": "n3b"}]}, "n2c": {"speaker": "gamemaster", "text": "The eye door leads to a room filled with illusions and shifting walls.", "text_fr": "La porte œil mène à une salle remplie d''illusions et de murs changeants.", "choices": [{"text": "Trust your instincts to navigate through the illusions.", "text_fr": "Fais confiance à ton instinct pour naviguer à travers les illusions.", "next": "n3c"}]}, "n3": {"speaker": "ally", "text": "(Whispers) I see a pattern in the flames — they pulse every three seconds.", "text_fr": "(Chuchote) Je vois un motif dans les flammes — elles pulsent toutes les trois secondes.", "choices": [{"text": "Time your movements with the pulse pattern.", "text_fr": "Synchronise tes mouvements avec le motif de pulsation.", "next": "n4"}]}, "n3b": {"speaker": "ally", "text": "(Whispers) The statue''s eyes are closed — as long as we''re quiet, we should be fine.", "text_fr": "(Chuchote) Les yeux de la statue sont fermés — tant qu''on est silencieux, on devrait aller bien.", "choices": [{"text": "Signal the party to move slowly and silently.", "text_fr": "Fais signe au groupe d''avancer lentement et silencieusement.", "next": "n4"}]}, "n3c": {"speaker": "ally", "text": "(Whispers) These walls aren''t real — focus on the ground beneath your feet instead.", "text_fr": "(Chuchote) Ces murs ne sont pas réels — concentre-toi plutôt sur le sol sous tes pieds.", "choices": [{"text": "Follow the ally''s advice, ignoring the shifting walls.", "text_fr": "Suis le conseil de l''allié, en ignorant les murs changeants.", "next": "n4"}]}, "n4": {"speaker": "gamemaster", "text": "(Regardless of path, your party reaches a central chamber with a locked chest.)", "text_fr": "(Quel que soit le chemin, votre groupe atteint une chambre centrale avec un coffre verrouillé.)", "choices": [{"text": "Examine the chest for any obvious traps before opening.", "text_fr": "Examine le coffre pour des pièges évidents avant de l''ouvrir.", "next": "n5"}, {"text": "Have the rogue in your party attempt to pick the lock.", "text_fr": "Demande au voleur de votre groupe de crocheter la serrure.", "next": "n5b"}]}, "n5": {"speaker": "gamemaster", "text": "You notice a faint poisoned needle mechanism hidden in the lock.", "text_fr": "Vous remarquez un mécanisme d''aiguille empoisonnée caché dans la serrure.", "choices": [{"text": "Disable the needle mechanism before proceeding.", "text_fr": "Désactive le mécanisme d''aiguille avant de continuer.", "next": "n6"}]}, "n5b": {"speaker": "ally", "text": "(Working carefully) I can feel a trap in here, give me a moment.", "text_fr": "(Travaillant prudemment) Je sens un piège là-dedans, laisse-moi un moment.", "choices": [{"text": "Wait patiently, letting them work.", "text_fr": "Attends patiemment, en les laissant travailler.", "next": "n6"}]}, "n6": {"speaker": "gamemaster", "text": "(Success!) The chest opens safely, revealing a glowing enchanted blade inside.", "text_fr": "(Succès !) Le coffre s''ouvre en toute sécurité, révélant une lame enchantée brillante à l''intérieur.", "choices": [{"text": "Take the blade, sensing its magical power.", "text_fr": "Prends la lame, sentant son pouvoir magique.", "next": "n7"}]}, "n7": {"speaker": "ally", "text": "That blade radiates powerful magic. This bodes well for what lies ahead.", "text_fr": "Cette lame dégage une magie puissante. C''est bon signe pour ce qui nous attend.", "choices": [{"text": "Let''s press onward, deeper into the dungeon.", "text_fr": "Avançons, plus profondément dans le donjon.", "next": "end_success"}]}, "end_success": {"speaker": "gamemaster", "text": "Your party presses forward, stronger and more prepared for what comes next.", "text_fr": "Votre groupe avance, plus fort et mieux préparé pour ce qui vient ensuite.", "end": true, "ending_label": "Salles du donjon explorées avec succès 🗝️⚔️"}}}'::jsonb, is_playable = true
where title = 'Explorer un donjon à plusieurs salles avec choix tactiques'
  and theme_id = (select id from scenario_themes where position = 9 and language_id = (select id from languages where code = 'en'));
